-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 19
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 19 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 19', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 19 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-19.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Cite os três pilares da segurança da informação.', 0.2, '**Confidencialidade**, **integridade** e **disponibilidade** (sigla CID; em inglês, CIA).', 'Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 1, 2, 'Diga qual pilar foi atingido em cada um dos três incidentes e cite uma proteção do banco para cada um.', 0.4, '(1) vazamento do CPF = **confidencialidade** (papéis e GRANT mínimos, permissão por coluna, visão, senha forte); (2) nota alterada = **integridade** (GRANT UPDATE só para quem pode, CHECK, trigger de validação, auditoria); (3) disco queimado = **disponibilidade** (backup automático e testado guardado em outro lugar, servidor estável, monitoramento).', 'Nota cheia (0,4): os três pilares certos + uma proteção coerente para cada. Metade (0,2): pilares certos sem as proteções, ou dois casos completos. Zero (0): pilares trocados.'),
      (v_atividade, 1, 3, 'Explique por que um backup guardado sem senha num pendrive ajuda um pilar e fere outro.', 0.4, 'O backup **ajuda a disponibilidade** (dá para recuperar os dados), mas, sem senha e num pendrive compartilhado, **fere a confidencialidade**: qualquer pessoa que pegar o pendrive lê o CPF dos alunos. Os pilares andam juntos.', 'Nota cheia (0,4): os dois pilares + o motivo. Metade (0,2): só um dos pilares com o motivo. Zero (0): pilares trocados ou sem relação.'),
      (v_atividade, 2, 1, 'Cite os quatro níveis de classificação da informação usados na aula.', 0.2, '**Pública**, **interna**, **restrita** e **confidencial**.', 'Nota cheia (0,2): os quatro. Metade (0,1): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 2, 2, 'Classifique cada um dos quatro dados do contexto num desses níveis.', 0.4, 'Nome do curso = **pública**; matrículas por turma = **interna**; e-mail do aluno = **restrita**; CPF do aluno = **confidencial**.', 'Nota cheia (0,4): os quatro certos. Metade (0,2): dois ou três certos. Zero (0): um ou nenhum (aceitar e-mail como confidencial se justificado como dado pessoal).'),
      (v_atividade, 2, 3, 'Explique por que a aplicação (back-end) não deve se conectar com o login postgres.', 0.4, 'O postgres é o **administrador** (pode tudo: apagar banco, criar papéis); se a senha vazar pelo back-end, o invasor **pode tudo**. A aplicação usa um login próprio (app_escola) com **só os comandos que o back-end usa** — menor privilégio; o postgres fica só com o DBA.', 'Nota cheia (0,4): poder total do postgres + login próprio com o mínimo. Metade (0,2): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 3, 1, 'Explique o princípio do menor privilégio.', 0.2, 'Cada usuário recebe **só as permissões necessárias** para o seu trabalho, nada "a mais por garantia"; se a senha vazar, o estrago fica limitado.', 'Nota cheia (0,2): só o necessário. Metade (0,1): ideia incompleta (ex.: "dar pouca permissão" sem ligar ao trabalho). Zero (0): sem relação ou "acesso total".'),
      (v_atividade, 3, 2, 'Escreva a linha da matriz de acesso do financeiro para as tabelas parcela e aluno, usando S, I, U e D (e as colunas, quando for o caso).', 0.4, 'Financeiro: **parcela = S e U só em data_pagamento** (sem I e sem D); **aluno = S só em id_aluno e nome** (sem I, U e D; não vê CPF nem telefone).', 'Nota cheia (0,4): as duas tabelas com as colunas certas e sem DELETE. Metade (0,2): uma tabela certa, ou as duas sem restringir as colunas. Zero (0): acesso total ou com DELETE.'),
      (v_atividade, 3, 3, 'Justifique por que ninguém recebe DELETE na tabela matricula.', 0.4, 'A matrícula é **cancelada** (situacao = ''cancelada'', procedimento da aula 17), **não apagada**: assim o **histórico** e as parcelas ficam guardados e ninguém apaga dado por engano ou de propósito — protege a **integridade** (e a disponibilidade).', 'Nota cheia (0,4): cancelar em vez de apagar + histórico/integridade. Metade (0,2): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 4, 1, 'Explique a diferença entre um papel de grupo e um papel de login no PostgreSQL.', 0.2, 'No PostgreSQL, usuário e grupo são o mesmo objeto, o **papel (role)**. O papel de **grupo** é criado com **NOLOGIN** e guarda as permissões; o papel de **login** tem **LOGIN** e senha, é uma pessoa, e entra no grupo para herdar as permissões.', 'Nota cheia (0,2): NOLOGIN × LOGIN + função de cada. Metade (0,1): só um dos lados. Zero (0): sem relação.'),
      (v_atividade, 4, 2, 'Escreva os comandos que criam os grupos grupo_secretaria, grupo_financeiro e grupo_consulta e o login ana_secretaria dentro do grupo da secretaria.', 0.4, 'CREATE ROLE grupo_secretaria NOLOGIN; CREATE ROLE grupo_financeiro NOLOGIN; CREATE ROLE grupo_consulta NOLOGIN; CREATE ROLE ana_secretaria **LOGIN PASSWORD** ''...'' **IN ROLE grupo_secretaria**; (ou CREATE ROLE ana_secretaria LOGIN PASSWORD ''...''; GRANT grupo_secretaria TO ana_secretaria;).', 'Nota cheia (0,4): três grupos NOLOGIN + login no grupo. Metade (0,2): grupos sem o login, ou login fora do grupo. Zero (0): CREATE TABLE ou sem relação.'),
      (v_atividade, 4, 3, 'Explique por que as permissões ficam no grupo e por que o login compartilhado prejudica a auditoria.', 0.4, 'Com as permissões no **grupo**, cada funcionária nova só ganha o **login no grupo** e **herda** as permissões, todas iguais, sem script novo. O login **compartilhado** faz a auditoria mostrar "secretaria" e **não quem fez**, e a senha no post-it fica exposta; cada pessoa precisa do **próprio login**.', 'Nota cheia (0,4): herança pelo grupo + auditoria sem saber quem. Metade (0,2): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 5, 1, 'Explique para que servem os comandos REVOKE ALL ... FROM PUBLIC no início do script.', 0.2, 'Todo papel recebe por padrão (PUBLIC) acesso ao banco e ao esquema; o **REVOKE ... FROM PUBLIC** tira esse acesso, e **só entra quem recebeu GRANT**.', 'Nota cheia (0,2): acesso padrão de todos + só quem recebeu GRANT. Metade (0,1): só "tira acesso". Zero (0): "apaga o banco" ou sem relação.'),
      (v_atividade, 5, 2, 'Escreva os GRANT que deixam a secretaria entrar no banco, enxergar o esquema e ter as permissões da matriz.', 0.4, 'GRANT **CONNECT** ON DATABASE escola_db TO grupo_secretaria; GRANT **USAGE** ON SCHEMA public TO grupo_secretaria; GRANT **SELECT, INSERT, UPDATE** ON aluno, matricula TO grupo_secretaria; GRANT **SELECT** ON curso, turma TO grupo_secretaria;', 'Nota cheia (0,4): CONNECT/USAGE + as permissões da matriz, para o grupo. Metade (0,2): falta CONNECT/USAGE, ou permissões a mais/a menos, ou dadas para a pessoa. Zero (0): GRANT ALL ou sem relação.'),
      (v_atividade, 5, 3, 'A coordenação decidiu que a secretaria não altera mais matrículas. Escreva o comando e explique o que muda para as secretárias.', 0.4, '**REVOKE UPDATE ON matricula FROM grupo_secretaria;** — como a permissão estava no **grupo**, **todas as secretárias** perdem o UPDATE na matrícula ao mesmo tempo (continuam com SELECT e INSERT); quem tentar alterar recebe *permission denied*.', 'Nota cheia (0,4): REVOKE certo + efeito em todas do grupo. Metade (0,2): só o comando ou só a explicação. Zero (0): GRANT, DROP ou DELETE.'),
      (v_atividade, 6, 1, 'Explique quando usar permissão por coluna em vez de permissão na tabela inteira.', 0.2, 'Quando a pessoa precisa de **algumas colunas** da tabela e **não pode ver ou alterar as outras** (ex.: dados pessoais como CPF) — menor privilégio.', 'Nota cheia (0,2): só as colunas necessárias + proteger as outras. Metade (0,1): ideia incompleta. Zero (0): sem relação.'),
      (v_atividade, 6, 2, 'Escreva os GRANT do financeiro na parcela (ler e alterar só data_pagamento) e no aluno (ler só id_aluno e nome).', 0.4, 'GRANT **SELECT, UPDATE (data_pagamento)** ON parcela TO grupo_financeiro; GRANT **SELECT (id_aluno, nome)** ON aluno TO grupo_financeiro; (aceitar GRANT SELECT ON parcela + GRANT UPDATE (data_pagamento) ON parcela separados).', 'Nota cheia (0,4): os dois GRANT com as colunas certas, para o grupo. Metade (0,2): só um deles certo. Zero (0): GRANT na tabela inteira (UPDATE ou SELECT sem colunas) ou ALL.'),
      (v_atividade, 6, 3, 'Diga o resultado de cada comando no login do financeiro e explique o que ele indica: SELECT cpf FROM aluno; UPDATE parcela SET data_pagamento = current_date WHERE id_matricula = 10 AND numero = 1; DELETE FROM parcela;', 0.4, 'SELECT cpf = **ERROR: permission denied** (não tem SELECT no CPF); o UPDATE de data_pagamento **funciona**; DELETE = **permission denied**. Os erros são o **resultado esperado**: mostram que a **matriz de acesso foi respeitada**.', 'Nota cheia (0,4): os três resultados + "erro esperado/matriz respeitada". Metade (0,2): resultados certos sem a explicação, ou dois resultados certos com ela. Zero (0): resultados trocados.'),
      (v_atividade, 7, 1, 'Diga o que é uma visão (VIEW).', 0.2, 'Uma **consulta salva com nome**, usada como se fosse uma tabela; o usuário recebe permissão na **visão** e não nas tabelas de baixo.', 'Nota cheia (0,2): consulta salva + permissão na visão. Metade (0,1): só "consulta salva". Zero (0): "cópia da tabela" ou sem relação.'),
      (v_atividade, 7, 2, 'Escreva a visão vw_matriculas_por_turma (código da turma, nome do curso e total de matrículas) e o GRANT para o grupo_consulta.', 0.4, 'CREATE VIEW vw_matriculas_por_turma AS SELECT t.codigo, c.nome AS curso, **count(m.id_matricula)** AS matriculas FROM turma t JOIN curso c ON c.id_curso = t.id_curso **LEFT JOIN** matricula m ON m.id_turma = t.id_turma **GROUP BY** t.codigo, c.nome; **GRANT SELECT ON vw_matriculas_por_turma TO grupo_consulta;**', 'Nota cheia (0,4): visão com junção, contagem e GROUP BY + GRANT na visão. Metade (0,2): visão sem o GRANT, ou GRANT sem a visão, ou JOIN em vez de LEFT JOIN. Zero (0): GRANT nas tabelas.'),
      (v_atividade, 7, 3, 'Explique o que acontece quando o login da coordenação executa SELECT * FROM matricula e por que isso é desejado.', 0.4, 'Dá **ERROR: permission denied**, porque a coordenação tem permissão **só na visão**, não na tabela matricula. É desejado: ela vê o **total por turma** e **nenhum dado de aluno** (menor privilégio, confidencialidade).', 'Nota cheia (0,4): permission denied + motivo + por que é bom. Metade (0,2): só o resultado ou só o motivo. Zero (0): "mostra as matrículas".'),
      (v_atividade, 8, 1, 'Diga qual comando do psql lista os papéis, os atributos e os grupos de cada um.', 0.2, '**\du** (lista os papéis, atributos como Cannot login e Superuser, e os grupos de que cada um é membro).', 'Nota cheia (0,2): \du. Metade (0,1): aponta o pgAdmin (Login/Group Roles). Zero (0): \dt, \dp ou outro.'),
      (v_atividade, 8, 2, 'Escreva duas formas de conferir as permissões da tabela parcela: o comando do psql e a consulta no information_schema.', 0.4, '**\dp parcela** (r = SELECT, a = INSERT, w = UPDATE, d = DELETE; Column privileges para as colunas) e SELECT grantee, privilege_type FROM **information_schema.role_table_grants** WHERE table_name = ''parcela'';', 'Nota cheia (0,4): as duas formas. Metade (0,2): só uma. Zero (0): nenhuma.'),
      (v_atividade, 8, 3, 'Escreva o comando que bloqueia o login do funcionário que saiu e o que faz o login do estagiário expirar, e explique por que as permissões do grupo não precisam ser refeitas.', 0.4, '**ALTER ROLE** funcionario **NOLOGIN**; (ou DROP ROLE) e **ALTER ROLE** estagiario **VALID UNTIL ''2026-12-31''**; As permissões ficam no **grupo**: tirar o login ou a pessoa do grupo não muda as permissões dos colegas, e o novo funcionário só entra no grupo.', 'Nota cheia (0,4): os dois comandos + explicação do grupo. Metade (0,2): só um comando com a explicação, ou os dois sem ela. Zero (0): apagar tabelas ou passar a senha ao colega.'),
      (v_atividade, 9, 1, 'Explique o que é auditoria de acesso e cite as duas camadas usadas no PostgreSQL.', 0.2, 'É o registro de **quem fez o quê, quando e em qual dado** (para investigar e provar responsabilidade — não repúdio). Camadas: **log do servidor** (postgresql.conf: log_connections, log_disconnections, log_statement = ''mod'') e **tabela de auditoria alimentada por trigger**.', 'Nota cheia (0,2): conceito + as duas camadas. Metade (0,1): só o conceito. Zero (0): confunde com backup.'),
      (v_atividade, 9, 2, 'Escreva a tabela auditoria, a função registrar_auditoria (com TG_TABLE_NAME, TG_OP, OLD e NEW) e o trigger AFTER na tabela parcela.', 0.4, 'CREATE TABLE auditoria (id_auditoria bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tabela text NOT NULL, operacao text NOT NULL, usuario text NOT NULL DEFAULT **session_user**, momento timestamptz NOT NULL DEFAULT **now()**, dados_antes **jsonb**, dados_depois **jsonb**); CREATE OR REPLACE FUNCTION registrar_auditoria() RETURNS trigger LANGUAGE plpgsql **SECURITY DEFINER** SET search_path = public AS $$ BEGIN INSERT INTO auditoria (tabela, operacao, dados_antes, dados_depois) VALUES (**TG_TABLE_NAME, TG_OP**, CASE WHEN TG_OP <> ''INSERT'' THEN **to_jsonb(OLD)** END, CASE WHEN TG_OP <> ''DELETE'' THEN **to_jsonb(NEW)** END); RETURN NULL; END; $$; CREATE TRIGGER trg_auditoria_parcela **AFTER INSERT OR UPDATE OR DELETE ON parcela FOR EACH ROW** EXECUTE FUNCTION registrar_auditoria();', 'Nota cheia (0,4): tabela com usuário/momento + função com TG_TABLE_NAME, TG_OP, OLD/NEW + trigger AFTER FOR EACH ROW. Metade (0,2): falta uma das três peças, ou sem antes/depois. Zero (0): sem trigger ou sem relação.'),
      (v_atividade, 9, 3, 'Explique por que a função usa SECURITY DEFINER e por que grava session_user e não current_user.', 0.4, '**SECURITY DEFINER** faz a função rodar com o **poder do dono**: ela grava na auditoria mesmo que os usuários **não tenham permissão** nela, e eles **não conseguem apagar o próprio rastro**. Dentro dela o **current_user vira o dono** da função; o **session_user** continua sendo o **login que conectou** — por isso grava quem fez de verdade.', 'Nota cheia (0,4): as duas explicações. Metade (0,2): só uma. Zero (0): invertido (current_user = login que conectou).'),
      (v_atividade, 10, 1, 'Explique o erro do trecho 1 e corrija.', 0.2, 'O back-end com **postgres** tem **poder total** e a senha no **JavaScript do site** fica visível para qualquer um. Correção: conectar com o login **app_escola** (só o que o back-end usa) e guardar a senha em **variável de ambiente**, nunca no Git nem no site.', 'Nota cheia (0,2): os dois erros + correção. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 2, 'Explique o problema do trecho 2 e corrija.', 0.4, '**GRANT ALL** dá permissões demais (inclusive DELETE e TRUNCATE) e **WITH GRANT OPTION** deixa o financeiro **repassar** a permissão — fere o menor privilégio. Correção: REVOKE ALL ON parcela FROM grupo_financeiro; GRANT SELECT, UPDATE (data_pagamento) ON parcela TO grupo_financeiro;', 'Nota cheia (0,4): os dois problemas + GRANT mínimo por coluna. Metade (0,2): só um problema, ou correção sem explicação. Zero (0): mantém o ALL.'),
      (v_atividade, 10, 3, 'Explique o problema do trecho 3 e corrija.', 0.4, 'Backup no **mesmo disco** se perde junto quando o disco queima, e backup **nunca restaurado** não é garantia — fere a **disponibilidade**. Correção: guardar o pg_dump **em outro lugar**, com **acesso restrito**, e fazer **teste de restauração** periódico.', 'Nota cheia (0,4): os dois problemas + correção. Metade (0,2): só um. Zero (0): nenhum.');
end $$;
